<title>Store — Orchard</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{--dark:#1d1d1f;--bg:#f5f5f7;--mid:#6e6e73;--blue:#0066cc;--white:#fff;--radius:18px;--card-radius:20px}
body{font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue",Helvetica,Arial,sans-serif;color:var(--dark);background:var(--white);font-size:17px;line-height:1.5;overflow-x:hidden}
a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}
/* Ribbon */
.ribbon{background:#1d1d1f;color:#f5f5f7;text-align:center;padding:10px 20px;font-size:13px}
.ribbon a{color:#fff;font-size:13px}
/* Nav */
nav{background:rgba(255,255,255,.85);backdrop-filter:saturate(180%) blur(20px);-webkit-backdrop-filter:saturate(180%) blur(20px);border-bottom:1px solid rgba(0,0,0,.08);position:sticky;top:0;z-index:100;height:44px;display:flex;align-items:center;justify-content:center}
.nav-inner{max-width:1200px;width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
.nav-logo{font-size:20px;font-weight:600;color:var(--dark);letter-spacing:-.02em}
.nav-links{display:flex;gap:28px}
.nav-links a{font-size:13px;color:var(--dark);opacity:.8;transition:opacity .2s}
.nav-links a:hover{opacity:1;text-decoration:none}
.nav-actions{display:flex;gap:20px}
.nav-actions a{font-size:13px;color:var(--dark);opacity:.8}
/* Store Hero */
.store-hero{text-align:center;padding:64px 24px 40px;background:var(--white)}
.store-hero h1{font-size:56px;font-weight:700;letter-spacing:-.04em;margin-bottom:8px}
.store-hero p{font-size:19px;color:var(--mid);margin-bottom:28px}
.hero-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.btn-outline{display:inline-block;padding:10px 22px;border:1px solid #d2d2d7;border-radius:24px;font-size:15px;font-weight:500;color:var(--dark);transition:all .2s;background:transparent}
.btn-outline:hover{background:var(--dark);color:#fff;text-decoration:none;border-color:var(--dark)}
.btn-solid{display:inline-block;padding:10px 22px;background:var(--blue);border-radius:24px;font-size:15px;font-weight:500;color:#fff;transition:all .2s}
.btn-solid:hover{background:#0055b3;text-decoration:none}
/* Product Icon Bar */
.icon-bar-wrap{background:var(--white);border-bottom:1px solid #d2d2d7;padding:16px 0;overflow-x:auto;scrollbar-width:none}
.icon-bar-wrap::-webkit-scrollbar{display:none}
.icon-bar{display:flex;gap:8px;padding:0 24px;min-width:max-content;max-width:1200px;margin:0 auto}
.icon-item{display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 16px;border-radius:12px;cursor:pointer;transition:background .2s;text-decoration:none;color:var(--dark);min-width:72px}
.icon-item:hover{background:var(--bg);text-decoration:none}
.icon-item .ico{font-size:28px}
.icon-item span{font-size:11px;font-weight:500;color:var(--mid);white-space:nowrap}
/* Section heading */
.sec-head{max-width:1200px;margin:0 auto 24px;padding:0 24px}
.sec-head h2{font-size:36px;font-weight:700;letter-spacing:-.03em;margin-bottom:4px}
.sec-head p{font-size:17px;color:var(--mid)}
.sec-head .promo{display:inline-block;margin-top:8px;font-size:14px;color:var(--blue);font-weight:500}
/* Carousel container */
.carousel-wrap{position:relative;margin-bottom:64px}
.carousel-outer{overflow:hidden;padding:0 24px}
.carousel{display:flex;gap:16px;transition:transform .4s cubic-bezier(.4,0,.2,1);will-change:transform}
/* Product cards */
.prod-card{min-width:220px;max-width:220px;background:var(--bg);border-radius:var(--card-radius);padding:20px;display:flex;flex-direction:column;flex-shrink:0}
.prod-card-img{height:140px;display:flex;align-items:center;justify-content:center;font-size:56px;margin-bottom:14px;border-radius:12px}
.badge{display:inline-block;background:var(--blue);color:#fff;font-size:10px;font-weight:700;letter-spacing:.05em;padding:2px 8px;border-radius:12px;margin-bottom:8px;width:fit-content}
.prod-card h3{font-size:17px;font-weight:600;margin-bottom:4px;letter-spacing:-.02em}
.prod-card .tagline{font-size:13px;color:var(--mid);margin-bottom:12px;flex:1}
.prod-card .price{font-size:15px;font-weight:600;color:var(--dark);margin-bottom:2px}
.prod-card .monthly{font-size:12px;color:var(--mid);margin-bottom:14px}
.prod-card .card-links{display:flex;gap:12px;flex-wrap:wrap}
.card-link{font-size:13px;font-weight:500;color:var(--blue)}
/* Arrow buttons */
.arrow-btn{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border-radius:50%;background:var(--white);border:1px solid #d2d2d7;box-shadow:0 2px 8px rgba(0,0,0,.12);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--dark);z-index:10;transition:all .2s;font-family:inherit}
.arrow-btn:hover{background:var(--dark);color:#fff;border-color:var(--dark)}
.arrow-prev{left:4px}
.arrow-next{right:4px}
/* Help cards */
.help-card{min-width:240px;max-width:240px;background:var(--bg);border-radius:var(--card-radius);padding:28px 24px;flex-shrink:0}
.help-card .ico{font-size:40px;margin-bottom:14px}
.help-card h3{font-size:18px;font-weight:600;margin-bottom:6px}
.help-card p{font-size:14px;color:var(--mid);margin-bottom:16px}
/* Store difference cards */
.diff-card{min-width:220px;max-width:220px;background:var(--bg);border-radius:var(--card-radius);padding:24px;flex-shrink:0}
.diff-card .ico{font-size:36px;margin-bottom:12px}
.diff-card h3{font-size:16px;font-weight:600;margin-bottom:6px}
.diff-card p{font-size:13px;color:var(--mid)}
/* Accessories / Audio cards */
.acc-card{min-width:200px;max-width:200px;background:var(--bg);border-radius:var(--card-radius);padding:20px;flex-shrink:0}
.acc-card-img{height:120px;display:flex;align-items:center;justify-content:center;font-size:48px;margin-bottom:12px}
.acc-card h3{font-size:14px;font-weight:600;margin-bottom:4px;line-height:1.3}
.acc-card .note{font-size:12px;color:var(--blue);margin-bottom:4px}
.acc-card .price{font-size:15px;font-weight:600}
/* Brand collab */
.brand-collab{background:linear-gradient(135deg,#1a1a2e 0%,#16213e 60%,#0f3460 100%);border-radius:var(--card-radius);margin:0 24px 64px;padding:60px 48px;color:#fff;display:flex;justify-content:space-between;align-items:center;gap:40px;flex-wrap:wrap}
.brand-collab h2{font-size:40px;font-weight:700;letter-spacing:-.03em;margin-bottom:8px}
.brand-collab p{font-size:17px;opacity:.8;margin-bottom:24px;max-width:480px}
.brand-collab .right{font-size:80px;opacity:.3}
/* Savings carousel cards */
.save-card{min-width:260px;max-width:260px;background:var(--bg);border-radius:var(--card-radius);padding:28px 24px;flex-shrink:0}
.save-card .ico{font-size:36px;margin-bottom:12px}
.save-card h3{font-size:18px;font-weight:600;margin-bottom:8px}
.save-card p{font-size:14px;color:var(--mid);margin-bottom:16px}
/* Quick links */
