.quick-links h2{font-size:28px;font-weight:700;letter-spacing:-.02em;margin-bottom:20px}
.ql-grid{display:flex;gap:12px;flex-wrap:wrap}
.ql-item{padding:12px 24px;border:1px solid #d2d2d7;border-radius:24px;font-size:15px;font-weight:500;color:var(--dark);cursor:pointer;transition:all .2s}
.ql-item:hover{background:var(--dark);color:#fff;border-color:var(--dark)}
/* Footer */
footer{background:#f5f5f7;padding:40px 24px;border-top:1px solid #d2d2d7}
.footer-inner{max-width:1200px;margin:0 auto}
.footer-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:24px;margin-bottom:32px}
.footer-col h4{font-size:12px;font-weight:600;color:var(--dark);margin-bottom:12px;cursor:pointer;display:flex;justify-content:space-between;align-items:center}
.footer-col h4 .toggle{display:none;font-size:14px;color:var(--mid);font-weight:400}
.footer-col ul{list-style:none}
.footer-col ul li{margin-bottom:8px}
.footer-col ul li a{font-size:12px;color:var(--mid)}
.footer-col ul li a:hover{color:var(--dark);text-decoration:none}
.footer-bottom{font-size:12px;color:var(--mid);border-top:1px solid #d2d2d7;padding-top:20px;line-height:1.8}
.footer-bottom a{color:var(--mid)}
.footer-bottom p{margin-bottom:8px}
.section-gap{height:64px}
@media(max-width:900px){
  .footer-grid{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:600px){
  .store-hero h1{font-size:36px}
  .footer-grid{grid-template-columns:1fr}
  .footer-col h4 .toggle{display:inline}
  .footer-col ul{display:none}
  .footer-col.open ul{display:block}
  .brand-collab{padding:40px 28px}
  .brand-collab h2{font-size:28px}
  .nav-actions{display:none}
}
</style>
