<script>
// Carousel state
const carouselState = {};

function getCarouselId(name) { return 'carousel-' + name; }

function scrollCarousel(name, dir) {
  const el = document.getElementById(getCarouselId(name));
  if (!el) return;
  const cards = el.children;
  if (!cards.length) return;
  const cardW = cards[0].offsetWidth + 16;
  const visible = Math.floor(el.parentElement.offsetWidth / cardW) || 1;
  const max = Math.max(0, cards.length - visible);
  if (!carouselState[name]) carouselState[name] = 0;
  carouselState[name] = Math.max(0, Math.min(max, carouselState[name] + dir));
  el.style.transform = 'translateX(-' + (carouselState[name] * cardW) + 'px)';
}

function toggleFooter(h4) {
  if (window.innerWidth > 600) return;
  const col = h4.parentElement;
  col.classList.toggle('open');
  const toggle = h4.querySelector('.toggle');
  if (toggle) toggle.textContent = col.classList.contains('open') ? '−' : '+';
}
</script>
